<?php
require_role(['admin']);$base='index.php?page=clubs';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'save';if($action==='delete'){db()->prepare('DELETE FROM clubs WHERE id=?')->execute([$id]);flash('Club supprimé. Les nageurs associés sont conservés sans club.');redirect($base);} $name=trim($_POST['name']??'');$city=trim($_POST['city']??'');$contact=trim($_POST['contact']??'');if(!$name)flash('Le nom du club est obligatoire.','error');elseif($id){db()->prepare('UPDATE clubs SET name=?,city=?,contact=? WHERE id=?')->execute([$name,$city,$contact,$id]);flash('Club modifié.');}else{db()->prepare('INSERT INTO clubs(name,city,contact) VALUES(?,?,?)')->execute([$name,$city,$contact]);flash('Club ajouté.');}redirect($base);}
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM clubs WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
?>
<div class="grid2"><section class="panel"><h3><?=$edit?'Modifier le club':'Ajouter un club'?></h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Nom du club</label><input name="name" required value="<?=e($edit['name']??'')?>"><label>Ville</label><input name="city" value="<?=e($edit['city']??'')?>"><label>Contact</label><input name="contact" value="<?=e($edit['contact']??'')?>"><button class="btn primary"><?=$edit?'Enregistrer':'Ajouter le club'?></button><?php if($edit):?> <a class="btn light" href="<?=$base?>">Annuler</a><?php endif;?></form></section><section class="panel"><h3>Clubs</h3><div class="table-wrap"><table><tr><th>Nom</th><th>Ville</th><th>Contact</th><th>Nageurs</th><th>Actions</th></tr><?php foreach(db()->query('SELECT c.*,COUNT(s.id) swimmers FROM clubs c LEFT JOIN swimmers s ON s.club_id=c.id GROUP BY c.id ORDER BY c.name') as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['city'])?></td><td><?=e($r['contact'])?></td><td><?=e($r['swimmers'])?></td><td class="actions"><a class="link" href="<?=$base?>&edit=<?=$r['id']?>">Modifier</a><form class="inline" method="post" onsubmit="return confirm('Supprimer ce club ?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="link danger">Supprimer</button></form></td></tr><?php endforeach;?></table></div></section></div>